// Ассеты V8: сгенерировано tools/assets/import.py — НЕ ПРАВИТЬ РУКАМИ.
// Источники, промпты и статусы: tools/assets/manifest.json; план и правила: V8.md.
// Фолбэк: нет картинки или ассеты выключены (?assets=0) — игра рисует всё кодом, как раньше.
G.assets = (function () {
  const data = {
    'arena_yard': 'data:image/png;base64,',
    'arena_field': 'data:image/png;base64,',
    'arena_forest': 'data:image/png;base64,',
    'arena_night': 'data:image/png;base64,',
    'arena_river': 'data:image/png;base64,',
    'arena_street': 'data:image/png;base64,',
    'arena_ring': 'data:image/png;base64,',
    'title': 'data:image/png;base64,',
    'title_dusk': 'data:image/png;base64,',
    'icon_leaf': 'data:image/png;base64,',
    'portrait_naruto': 'data:image/png;base64,',
    'portrait_sasuke': 'data:image/png;base64,',
    'portrait_sakura': 'data:image/png;base64,',
    'portrait_iruka': 'data:image/png;base64,',
    'portrait_hinata': 'data:image/png;base64,',
    'portrait_shikamaru': 'data:image/png;base64,',
    'portrait_kiba': 'data:image/png;base64,',
    'portrait_mizuki': 'data:image/png;base64,',
    'portrait_kakashi': 'data:image/png;base64,',
    'portrait_lee': 'data:image/png;base64,',
    'portrait_choji': 'data:image/png;base64,',
    'portrait_ino': 'data:image/png;base64,',
    'portrait_shino': 'data:image/png;base64,',
    'portrait_guy': 'data:image/png;base64,',
    'portrait_anko': 'data:image/png;base64,',
    'portrait_asuma': 'data:image/png;base64,',
    'portrait_konohamaru': 'data:image/png;base64,',
    'portrait_neji': 'data:image/png;base64,',
    'portrait_hokage': 'data:image/png;base64,',
    'portrait_teuchi': 'data:image/png;base64,',
  };
  const cache = {};
  const cbs = [];
  let loaded = 0, fired = false;
  const total = Object.keys(data).length;
  const api = {
    enabled: true,
    data,
    has(id) { return !!data[id]; },
    img(id) {
      if (!data[id]) return null;
      if (!cache[id]) {
        const i = new Image();
        i.onload = () => { loaded++; if (loaded >= total && !fired) { fired = true; cbs.splice(0).forEach((f) => f()); } };
        i.src = data[id];
        cache[id] = i;
      }
      return cache[id];
    },
    ready(id) { const i = cache[id]; return !!(i && i.complete && (i.naturalWidth || i.width) > 0); },
    onReady(fn) { if (fired) fn(); else cbs.push(fn); },
    preload() { for (const id in data) this.img(id); },
    canvas(id, w, h) {
      if (!this.enabled || !this.ready(id)) return null;
      const c = G.gfx.canvas(w, h), x = c.getContext('2d');
      x.imageSmoothingEnabled = false;
      x.drawImage(cache[id], 0, 0, w, h);
      c._asset = id;
      return c;
    },
    draw(ctx, id, x, y, w, h) {
      if (!this.enabled || !this.ready(id)) return false;
      ctx.drawImage(cache[id] || this.img(id), x, y, w, h);
      return true;
    },
  };
  try {
    if (typeof location !== 'undefined' && /[?&]assets=0/.test(location.search)) api.enabled = false;
  } catch (_) {}
  api.preload();
  return api;
})();
